pub(super) fn fabric_artifacts(runtime: ReadyProfile) -> Option<&'static [VoiceArtifact]> {
    match runtime {
        ReadyProfile::Fabric1165 => Some(FABRIC_0),
        ReadyProfile::Fabric1192 => Some(FABRIC_1),
        ReadyProfile::Fabric1201 => Some(FABRIC_2),
        ReadyProfile::Fabric1211 => Some(FABRIC_3),
        _ => None,
    }
}
pub(super) fn forge_installer(runtime: ReadyProfile) -> Option<VoiceArtifact> {
    crate::engine::connect_forge_installer_pins::ForgeInstallerPin::for_runtime(runtime).map(
        |pin| VoiceArtifact {
            relative: pin.filename,
            bytes: pin.bytes,
            sha256: pin.sha256,
            url: pin.url,
        },
    )
}
